using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "StarBeamAction", menuName = "Data/Battle/Battle Actions/Event/StarBeam Action")]
public class StarBeamAction : PurifyCorruptWithMultiplierActions
{
	[SerializeField]
	private int starShardsAmount;

	public int StarShardsAmount => starShardsAmount;

	public override int PurifyCounter(bool checkConditionToBeCastedOrPreview)
	{
		return Mathf.FloorToInt((float)ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentGold / (float)starShardsAmount);
	}
}
